async function createAppointment(env,u,c,b,options={}){allowed(u,c,'book');const catalog=plans(c);let bookingUser=u;if(u.role==='manager'&&b.customer){bookingUser=await first(env.DB,'SELECT * FROM users WHERE id=? AND disabled=0',b.customer);if(!bookingUser)throw err('Cliente não encontrado.');}const s=serviceCatalog(c,SERVICES).find(x=>x.id===b.service);if(!s||!validDate(b.date||'')||!/^\d{2}:(00|30)$/.test(b.time||''))throw err('Escolha um serviço, data e horário válidos.');const start=new Date(b.date+'T'+b.time+':00-03:00');if(!Number.isFinite(+start)||+start<Date.now()+bookingRules(c).leadMinutes*60000||+start>Date.now()+bookingRules(c).maxDays*86400000)throw err('Escolha um horário dentro da antecedência e do prazo configurados.');if(!bookingUser.phone)throw err('Complete seu telefone no perfil antes de agendar.');const barber=(await professionals(env.DB,c)).find(x=>x.id===b.barber);if(!barber)throw err('Profissional indisponível.');const [hh,mm]=b.time.split(':').map(Number),minute=hh*60+mm,hours=c.hours||{open:'09:00',close:'20:00'};const toMin=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]);if(minute<toMin(hours.open)||minute+s.minutes>toMin(hours.close))throw err('Horário fora do expediente.');const day=new Date(b.date+'T12:00:00Z').getUTCDay();let price=[2,3].includes(day)?s.discount||s.price:s.price;
let dependent=null;if(b.dependent){dependent=await first(env.DB,'SELECT * FROM dependents WHERE id=? AND user_id=? AND active=1',b.dependent,bookingUser.id);if(!dependent)throw err('Dependente inválido.');}let limited=false;if(b.kind==='club'){const m=await first(env.DB,'SELECT * FROM memberships WHERE user_id=?',bookingUser.id),plan=catalog.find(x=>x.id===m?.plan_id);if(!m||m.status!=='active'||m.paid_until<=now()||!plan)throw err('É necessário um clube ativo e pago para usar esse benefício.');if(dependent&&(!plan.id.includes('filho')||!['corte','sobrancelha'].includes(s.id)))throw err('O benefício do dependente cobre corte e sobrancelha no plano Pai e Filho.');if(!plan.days.includes(day))throw err('Seu plano não cobre esse dia da semana.');if(!['corte','sobrancelha'].includes(s.id)&&!(plan.id.includes('barba')&&['barba','combo'].includes(s.id)))throw err('Esse serviço não está incluso no seu plano.');if(plan.limit&&s.id==='barba')throw err('No One, agende o serviço completo de corte e barba.');if(plan.limit&&['corte','combo'].includes(s.id))limited=true;if(plan.limit){const count=await first(env.DB,"SELECT COUNT(*) n FROM appointments WHERE user_id=? AND kind='club' AND service IN ('corte','combo') AND status<>'canceled' AND substr(date,1,7)=? AND id<>?",bookingUser.id,b.date.slice(0,7),options.previous||'');if(count.n>=plan.limit&&['corte','combo'].includes(s.id))throw err('O limite de corte deste mês já foi utilizado ou reservado.')}price=0;}
if(!['club','single'].includes(b.kind))throw err('Modalidade inválida.');const id=options.id||crypto.randomUUID();const batch=[...(options.previous?[env.DB.prepare('INSERT INTO appointment_transitions(appointment_id,action,created_at) VALUES(?,?,?)').bind(options.previous,'rescheduled',now()),env.DB.prepare('DELETE FROM slots WHERE appointment_id=?').bind(options.previous),env.DB.prepare('DELETE FROM monthly_usage WHERE appointment_id=?').bind(options.previous),env.DB.prepare("UPDATE appointments SET status='canceled' WHERE id=? AND status='scheduled'").bind(options.previous)]:[]),env.DB.prepare('INSERT INTO appointments(id,user_id,barber_id,date,time,service,duration,price,kind) VALUES(?,?,?,?,?,?,?,?,?)').bind(id,bookingUser.id,b.barber,b.date,b.time,s.id,s.minutes,price,b.kind)];for(let i=0;i<s.minutes;i+=30){const t=minute+i;batch.push(env.DB.prepare('INSERT INTO slots(barber_id,date,time,appointment_id) VALUES(?,?,?,?)').bind(b.barber,b.date,String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0'),id))}if(limited)batch.push(env.DB.prepare('INSERT INTO monthly_usage(user_id,month,appointment_id) VALUES(?,?,?)').bind(bookingUser.id,b.date.slice(0,7),id));if(dependent)batch.push(env.DB.prepare('UPDATE appointments SET dependent_id=? WHERE id=?').bind(dependent.id,id));batch.push(...appointmentNotificationStatements(env.DB,{id,user_id:bookingUser.id,date:b.date,time:b.time}));if(options.channel)batch.push(env.DB.prepare('INSERT INTO appointment_channels(appointment_id,channel) VALUES(?,?)').bind(id,options.channel));try{await env.DB.batch(batch)}catch(e){if(String(e).includes('UNIQUE'))throw err('Esse horário acabou de ser reservado. Escolha outro.',409);throw e}return {ok:true,id,price}}
