function owner(u){return u.email.toLowerCase()===OWNER}
async function identity(req,db){const id=req.headers.get('oai-authenticated-user-id'),email=req.headers.get('oai-authenticated-user-email');if(!id||!email)throw err('Entre com sua conta para continuar.',401);let u=await first(db,'SELECT * FROM users WHERE id=?',id);if(!u){let name=req.headers.get('oai-authenticated-user-full-name')||email.split('@')[0];if(req.headers.get('oai-authenticated-user-full-name-encoding')==='percent-encoded-utf-8')try{name=decodeURIComponent(name)}catch{}await run(db,'INSERT OR IGNORE INTO users(id,email,name,role) VALUES(?,?,?,?)',id,email,name,email.toLowerCase()===OWNER?'manager':'client');u=await first(db,'SELECT * FROM users WHERE id=?',id)}if(u.email.toLowerCase()!==email.toLowerCase())throw err('Sua identidade mudou. Fale com o proprietário para revisar o acesso.',403);if(email.toLowerCase()===OWNER)u.role='manager';else{const invite=await first(db,'SELECT * FROM team_invites WHERE email=?',email.toLowerCase());if(invite){await db.batch([db.prepare("UPDATE users SET role=?,permissions='{}' WHERE id=?").bind(invite.role,id),db.prepare('DELETE FROM team_invites WHERE email=?').bind(email.toLowerCase())]);u.role=invite.role;u.permissions='{}'}if(u.disabled)throw err('Seu acesso foi pausado pelo gestor. Entre em contato com a barbearia.',403)}return u}
