async function boundedText(req,limit){
 const declared=req.headers.get('content-length');if(declared&&(!/^\d+$/.test(declared)||Number(declared)>limit))throw err('Solicitação muito grande.',413);
 if(!req.body)return '';const reader=req.body.getReader(),decoder=new TextDecoder();let bytes=0,text='';
 try{while(true){const {done,value}=await reader.read();if(done)break;bytes+=value.byteLength;if(bytes>limit){await reader.cancel();throw err('Solicitação muito grande.',413)}text+=decoder.decode(value,{stream:true})}return text+decoder.decode()}finally{reader.releaseLock()}
}
async function body(req){if(req.headers.get('content-type')?.split(';')[0].trim().toLowerCase()!=='application/json')throw err('Formato inválido.',415);let value;try{value=JSON.parse(await boundedText(req,20000))}catch(e){if(e.status)throw e;throw err('Dados inválidos.')}
 if(!value||typeof value!=='object'||Array.isArray(value))throw err('Dados inválidos.');return value;
}
const rateTables=new WeakSet();
async function limitRequests(db,id,write,path){
 if(!rateTables.has(db)){await run(db,'CREATE TABLE IF NOT EXISTS security_limits (id TEXT PRIMARY KEY, hits INTEGER NOT NULL, expires_at INTEGER NOT NULL)');rateTables.add(db)}
 const bucket=Math.floor(now()/60),group=path==='/api/connect-account'?'credentials':write?'write':'read',limit=group==='credentials'?5:write?30:180,key=JSON.stringify([id,group,bucket]);
 await run(db,'INSERT INTO security_limits(id,hits,expires_at) VALUES(?,1,?) ON CONFLICT(id) DO UPDATE SET hits=hits+1',key,(bucket+2)*60);
 const row=await first(db,'SELECT hits FROM security_limits WHERE id=?',key);
 if(row.hits>limit)throw err('Muitas solicitações. Aguarde um minuto e tente novamente.',429);
 await run(db,'DELETE FROM security_limits WHERE expires_at<?',now());
}
function requestGuard(req,url){
 if(!['GET','POST'].includes(req.method))throw err('Método não permitido.',405);
 if(url.pathname==='/api/whatsapp/webhook')return;
 if(url.pathname==='/api/automation/tick')return;
 if(url.pathname==='/api/webhook'){if(req.method!=='POST')throw err('Método não permitido.',405);return}
 const site=req.headers.get('sec-fetch-site');if(site==='cross-site')throw err('Origem não permitida.',403);
 if(req.method==='POST'&&req.headers.get('origin')!==url.origin)throw err('Origem não permitida.',403);
}
async function stripe(env,path,params,method='POST',key){const headers={Authorization:'Bearer '+env.STRIPE_SECRET_KEY,'Stripe-Version':'2026-08-26.dahlia'};if(key)headers['Idempotency-Key']=key;let payload;if(params){headers['Content-Type']='application/x-www-form-urlencoded';payload=new URLSearchParams(params)}const r=await fetch('https://api.stripe.com/v1/'+path,{method,headers,body:payload});const j=await r.json();if(!r.ok)throw err('O processador não concluiu a operação. Confira a configuração ou tente novamente.',502);return j}
export async function verifySignature(raw,header,secret){if(!secret||!header)return false;const parts=header.split(','),t=parts.find(x=>x.startsWith('t='))?.slice(2);if(!t||!/^\d{10,}$/.test(t)||!Number.isFinite(Number(t))||Math.abs(now()-Number(t))>300)return false;const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']);const sig=Array.from(new Uint8Array(await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(t+'.'+raw))),x=>x.toString(16).padStart(2,'0')).join('');return parts.filter(x=>x.startsWith('v1=')).some(x=>{const v=x.slice(3);let diff=v.length^sig.length;for(let i=0;i<sig.length;i++)diff|=sig.charCodeAt(i)^(v.charCodeAt(i)||0);return diff===0})}
