async function cipherKey(env){if(!env.CONNECTION_MASTER_KEY)throw err('Conexão segura indisponível. Entre em contato com a gestão.',503);return crypto.subtle.importKey('raw',Uint8Array.from(atob(env.CONNECTION_MASTER_KEY),c=>c.charCodeAt(0)),{name:'AES-GCM'},false,['encrypt','decrypt'])}
export async function sealCredentials(value,env){const iv=crypto.getRandomValues(new Uint8Array(12)),key=await cipherKey(env);const buf=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(value)));return {iv:btoa(String.fromCharCode(...iv)),data:btoa(String.fromCharCode(...new Uint8Array(buf)))}}
export async function openCredentials(value,env){const key=await cipherKey(env),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:Uint8Array.from(atob(value.iv),c=>c.charCodeAt(0))},key,Uint8Array.from(atob(value.data),c=>c.charCodeAt(0)));return JSON.parse(new TextDecoder().decode(plain))}
async function paymentEnv(env){const row=await first(env.DB,"SELECT value FROM config WHERE key='payment_credentials'");if(!row)return env;const value=await openCredentials(JSON.parse(row.value),env);return {...env,...value}}
async function connectAccount(req,env,u,c){const b=await body(req);if(b.provider!=='stripe')throw err('A integração automática da InfinitePay ainda não está disponível nesta versão.');if(!/^(rk|sk)_live_[a-zA-Z0-9]{12,}$/.test(b.key||'')||!/^whsec_[a-zA-Z0-9]{12,}$/.test(b.webhook||'')||!/^pmc_[a-zA-Z0-9]{5,}$/.test(b.configuration||''))throw err('Informe credenciais Stripe de produção, segredo de confirmação e configuração de cartão válidos.');if(b.consent!=='on')throw err('Confirme que esta conta pertence à barbearia.');const values={STRIPE_SECRET_KEY:b.key,STRIPE_WEBHOOK_SECRET:b.webhook,STRIPE_CARD_CONFIGURATION:b.configuration};const remote={...env,...values};const account=await stripe(remote,'account',null,'GET');if(!account.charges_enabled)throw err('A conta ainda não está habilitada para cobrar. Conclua a verificação na Stripe.');const configuration=await stripe(remote,'payment_method_configurations/'+encodeURIComponent(b.configuration),null,'GET');if(!configuration.active||!configuration.card?.available||configuration.card?.display_preference?.value!=='on')throw err('A configuração precisa estar ativa e habilitar cartão.');for(const [k,v] of Object.entries(configuration)){if(v&&typeof v==='object'&&v.display_preference?.value==='on'&&!['card','apple_pay','google_pay'].includes(k))throw err('Desative outros meios de pagamento na configuração. Este sistema aceita somente crédito.');}const encrypted=await sealCredentials(values,env);const same=c.connection?.accountId===account.id;const connection={provider:'stripe',accountId:account.id,name:account.business_profile?.name||account.settings?.dashboard?.display_name||'Conta Stripe',enabled:false,webhookValidated:false,connectedAt:new Date().toISOString()};if(!same&&await first(env.DB,"SELECT user_id FROM memberships WHERE subscription_id IS NOT NULL AND status NOT IN ('canceled','incomplete_expired') LIMIT 1"))throw err('Não é possível trocar a conta enquanto houver assinaturas vinculadas.');await env.DB.batch([env.DB.prepare("INSERT INTO config(key,value) VALUES('payment_credentials',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value").bind(JSON.stringify(encrypted)),env.DB.prepare("INSERT INTO config(key,value) VALUES('connection',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value").bind(JSON.stringify(connection))]);return json({ok:true,message:'Conta conectada com segurança. Valide o evento de teste e revise os valores antes de ativar.'})}
export const PERMISSION_DEFAULTS={client:{book:true,cancel:true,changeplan:true,assistant:true},barber:{book:true,cancel:true,complete:true,contacts:false,metrics:true,assistant:true},manager:{book:true,cancel:true,complete:true,contacts:true,metrics:true,finance:true,settings:true,clients:true,assistant:true,professional:false}};
export function permissionsFor(u,c){if(owner(u))return Object.fromEntries([...new Set(Object.values(PERMISSION_DEFAULTS).flatMap(x=>Object.keys(x)))].map(k=>[k,true]));let custom={};try{custom=JSON.parse(u.permissions||'{}')}catch{}return {...PERMISSION_DEFAULTS[u.role],...c.policies?.[u.role],...custom}}
function allowed(u,c,key){if(!owner(u)&&permissionsFor(u,c)[key]!==true)throw err('Esta ação foi desativada pelo gestor para o seu perfil.',403)}
function requireOwner(u){if(!owner(u))throw err('Somente o proprietário pode alterar gestores, acessos e conexões.',403)}
async function audit(db,actor,target,action,detail){return run(db,'INSERT INTO audit_log(id,actor_id,target_id,action,detail) VALUES(?,?,?,?,?)',crypto.randomUUID(),actor,target,action,JSON.stringify(detail))}
function period(url){const end=url.searchParams.get('end')||today(),start=url.searchParams.get('start')||new Date(new Date(end+'T12:00:00Z').getTime()-29*86400000).toISOString().slice(0,10);if(!validDate(start)||!validDate(end)||start>end||(new Date(end)-new Date(start))/86400000>365)throw err('Escolha um período válido de até 366 dias.');return {start,end}}
