async function professionals(db,c){const rows=await all(db,"SELECT id,name,email,role,permissions FROM users WHERE role IN ('barber','manager') AND disabled=0 ORDER BY name");return rows.filter(b=>b.role==='barber'||owner(b)||permissionsFor(b,c).professional).map(b=>({id:b.id,name:b.name}))}
