async function systemDiagnostics(env,u,c){
 requireOwner(u);
 const w=await whatsappEnv(env);
 const latestRun=await first(env.DB,'SELECT started_at,finished_at,status FROM automation_runs ORDER BY started_at DESC LIMIT 1');
 const outbox=await all(env.DB,'SELECT status,COUNT(*) count FROM wa_outbox GROUP BY status');
 const notifications=await all(env.DB,'SELECT status,COUNT(*) count FROM wa_notifications GROUP BY status');
 const exceptions=[];
 const add=(code,message,action)=>exceptions.push({code,message,action});
 if(!ready(env,c))add('payments_setup','Cobranças não estão liberadas pela configuração atual.','Revisar conexão, confirmação assinada e aprovação dos preços em Configurações.');
 if(!waReady(w))add('whatsapp_setup','Credenciais completas do WhatsApp não estão configuradas.','Conectar o número oficial e o aplicativo Meta no painel WhatsApp.');
 if(!c.whatsapp?.enabled)add('whatsapp_paused','Envios de WhatsApp estão pausados.','Ativar somente após conferir número, consentimento e modelos aprovados.');
 const schedulerDeclared=env.AUTOMATION_SCHEDULE_CONFIGURED==='true';
 if(!schedulerDeclared)add('scheduler_missing','Executor periódico não está marcado como configurado.','Conectar um agendador e verificar uma execução real antes de habilitar o indicador.');
 const recentRun=!!(latestRun?.status==='success'&&latestRun.finished_at>=now()-900);
 if(schedulerDeclared&&!recentRun)add('automation_stale','Não há processamento concluído com sucesso nos últimos 15 minutos.','Revisar o executor e os registros de processamento.');
 for(const row of outbox)if(['failed','blocked','uncertain'].includes(row.status)&&row.count)add('outbox_'+row.status,row.count+' envio(s) com status '+row.status+'.','Revisar a fila no WhatsApp. Entrega incerta exige conferência antes de reenviar.');
 return json({checkedAt:now(),scope:'single_business',payments:{configured:ready(env,c),livePaymentVerified:false,verificationNote:'Configuração não comprova uma cobrança e repasse completos.'},whatsapp:{configured:waReady(w),enabled:!!c.whatsapp?.enabled,ai:false},automation:{schedulerDeclared,recentSuccessfulProcessing:recentRun,latestRun,note:'Processamento recente também pode ter sido acionado manualmente ou por webhook; não comprova o agendador.'},queues:{outbox,notifications},exceptions,roadmap:[{name:'Multiempresa',status:'Não implementado: base atual pertence à Barbearia do João.'},{name:'Instagram e Studio AI',status:'Não implementados: exigem conexão Meta, processamento de vídeos e limites de custo.'},{name:'IA de atendimento',status:'Não implementada: assistente atual usa regras e comandos.'},{name:'Comunidade e educadores',status:'Área EU SOU com cursos, aulas, eventos e acesso vinculado a recebimento registrado. Recorrência e IA ainda pendentes.'}]});
}
