 await run(db,'UPDATE wa_contacts SET pending=NULL WHERE wa_id=?',contact.wa_id);if(pending.previous)await run(db,"UPDATE wa_notifications SET status='canceled' WHERE reference_id=? AND status='pending'",pending.previous);
