 const reschedule=text.match(/^REMARCAR\s+(\d+)\s+(\d{4}-\d{2}-\d{2})$/),book=text.match(/^AGENDAR\s+(\d{4}-\d{2}-\d{2})(?:\s+(\w+))?$/);
