async function whatsappWebhook(req,env,url){
 if(req.method==='GET'){if(!env.WHATSAPP_VERIFY_TOKEN||url.searchParams.get('hub.mode')!=='subscribe'||url.searchParams.get('hub.verify_token')!==env.WHATSAPP_VERIFY_TOKEN)return json({error:'Verificação inválida'},403);return new Response(url.searchParams.get('hub.challenge')||'',{headers:{'Cache-Control':'no-store'}})}
 const raw=await boundedText(req,262144);if(!await verifyMetaSignature(raw,req.headers.get('x-hub-signature-256'),env.WHATSAPP_APP_SECRET))return json({error:'Assinatura inválida'},401);
 const configuration=await conf(env.DB);if(!configuration.whatsapp?.enabled||configuration.automation?.paused)return json({received:true,paused:true});
 let event;try{event=JSON.parse(raw)}catch{throw err('Evento inválido.')};if(event.object!=='whatsapp_business_account')throw err('Evento inválido.');
 for(const entry of event.entry||[])for(const change of entry.changes||[]){const v=change.value;if(v?.metadata?.phone_number_id!==env.WHATSAPP_PHONE_NUMBER_ID)continue;
 for(const status of v.statuses||[]){if(!['sent','delivered','read','failed'].includes(status.status))continue;await run(env.DB,"UPDATE wa_outbox SET status=?,error_code=? WHERE remote_id=? AND status NOT IN ('read','canceled')",status.status,status.errors?.[0]?.code?String(status.errors[0].code):null,status.id)}
 for(const message of (v.messages||[]).slice(0,50)){
 if(!/^\d{8,16}$/.test(message.from||'')||typeof message.id!=='string'||message.id.length>255)continue;
 if(await first(env.DB,'SELECT id FROM wa_inbox WHERE id=?',message.id))continue;
 await run(env.DB,'INSERT OR IGNORE INTO wa_contacts(wa_id,last_inbound) VALUES(?,?)',message.from,now());
 const lock=await run(env.DB,'UPDATE wa_contacts SET lease_until=? WHERE wa_id=? AND lease_until<?',now()+120,message.from,now());if(!lock.meta?.changes&&!lock.changes)return json({error:'Conversa em processamento; tente novamente.'},503);
 try{if(await first(env.DB,'SELECT id FROM wa_inbox WHERE id=?',message.id))continue;
 const contact=await first(env.DB,'SELECT * FROM wa_contacts WHERE wa_id=?',message.from);await run(env.DB,'UPDATE wa_contacts SET last_inbound=? WHERE wa_id=?',Math.max(contact.last_inbound,Math.min(Number(message.timestamp)||now(),now())),message.from);
 await limitRequests(env.DB,'wa:'+message.from,true,'conversation');let reply;try{reply=await waConversation(env,contact,message,url)}catch(e){if(!e.status)throw e;reply=e.message}
 const ops=[env.DB.prepare('INSERT OR IGNORE INTO wa_inbox(id,wa_id,kind,created_at) VALUES(?,?,?,?)').bind(message.id,message.from,message.type||'unknown',now())];if(reply)ops.push(env.DB.prepare('INSERT OR IGNORE INTO wa_outbox(id,wa_id,kind,text,created_at) VALUES(?,?,?,?,?)').bind('reply:'+message.id,message.from,'reply',reply.slice(0,3500),now()));await env.DB.batch(ops);
 }finally{await run(env.DB,'UPDATE wa_contacts SET lease_until=0 WHERE wa_id=?',message.from)}
 }
 }
 // Durable outbox: webhook acknowledges after processing; delivery failures remain visible for the operator.
 await automationTick(await paymentEnv(env));return json({received:true});
}
async function waDrain(env,limit=20){
 if(!waReady(env))return {sent:0,pendingConnection:true};const c=await conf(env.DB);if(!c.whatsapp?.enabled||c.automation?.paused)return {sent:0,paused:true};let sent=0;
 // A crashed/ambiguous send is not retried automatically: Meta has no send idempotency key.
 await run(env.DB,"UPDATE wa_outbox SET status='uncertain',error_code='INTERRUPTED' WHERE status='sending' AND created_at<?",now()-300);
 const rows=await all(env.DB,"SELECT o.*,c.last_inbound,c.consent,c.mode,c.user_id FROM wa_outbox o JOIN wa_contacts c ON c.wa_id=o.wa_id WHERE o.status='pending' ORDER BY o.created_at LIMIT ?",limit);
 for(const row of rows){
 if(row.kind!=='reply'&&row.user_id){const active=await first(env.DB,"SELECT id FROM users WHERE id=? AND disabled=0",row.user_id);const notification=await first(env.DB,'SELECT * FROM wa_notifications WHERE id=?',row.id);let obsolete=!active||notification?.status==='canceled';if(notification?.kind==='payment_failed'){const invoice=await first(env.DB,'SELECT status FROM invoices WHERE id=?',notification.reference_id);obsolete||=invoice?.status==='paid'}if(notification?.kind.startsWith('appointment_')){const appointment=await first(env.DB,'SELECT status,date,time FROM appointments WHERE id=?',notification.reference_id);obsolete||=!appointment||appointment.status!=='scheduled'||new Date(appointment.date+'T'+appointment.time+':00-03:00')<=Date.now()}if(obsolete){await run(env.DB,"UPDATE wa_outbox SET status='canceled' WHERE id=?",row.id);continue}}
 if(row.kind!=='reply'&&!row.consent){await run(env.DB,"UPDATE wa_outbox SET status='canceled' WHERE id=?",row.id);continue}
 const inWindow=row.last_inbound>now()-86400;let payload={messaging_product:'whatsapp',recipient_type:'individual',to:row.wa_id,type:'text',text:{preview_url:false,body:row.text}};
 if(!inWindow){const template=c.whatsapp?.templates?.[row.kind];if(!template){await run(env.DB,"UPDATE wa_outbox SET status='blocked',error_code='TEMPLATE_REQUIRED' WHERE id=?",row.id);continue}payload={messaging_product:'whatsapp',to:row.wa_id,type:'template',template:{name:template,language:{code:'pt_BR'},components:[{type:'body',parameters:[{type:'text',text:row.text}]}]}};}
 const claim=await run(env.DB,"UPDATE wa_outbox SET status='sending' WHERE id=? AND status='pending'",row.id);if(!claim.meta?.changes&&!claim.changes)continue;
 try{const result=await waGraph(env,env.WHATSAPP_PHONE_NUMBER_ID+'/messages',payload);if(!result.messages?.[0]?.id)throw err('Resposta inválida da Meta.',502);await run(env.DB,"UPDATE wa_outbox SET status='sent',remote_id=?,sent_at=? WHERE id=?",result.messages[0].id,now(),row.id);sent++}catch(e){await run(env.DB,'UPDATE wa_outbox SET status=?,error_code=? WHERE id=?',e.providerCode?'failed':'uncertain',e.providerCode||'DELIVERY_UNKNOWN',row.id)}
 }
 return {sent};
}
async function automationTickRoute(req,env){if(req.method!=='POST')throw err('Método não permitido.',405);if(!env.AUTOMATION_JOB_TOKEN||req.headers.get('authorization')!=='Bearer '+env.AUTOMATION_JOB_TOKEN)throw err('Sem permissão.',401);return json(await automationTick(await whatsappEnv(await paymentEnv(env))))}
async function automationTick(env){
 const settings=await conf(env.DB);if(settings.automation?.paused)return {ok:true,sent:0,paused:true};if(!waReady(env)||!settings.whatsapp?.enabled)return {ok:true,sent:0,pendingConnection:!waReady(env),paused:!settings.whatsapp?.enabled};
 const id=crypto.randomUUID();await run(env.DB,'INSERT INTO automation_runs(id,started_at,status) VALUES(?,?,?)',id,now(),'running');
 try{
 const day=Number(today().slice(-2));if((settings.automation?.days||[10,20]).includes(day)){const due=await all(env.DB,"SELECT i.id,i.user_id FROM invoices i JOIN wa_contacts w ON w.user_id=i.user_id WHERE i.status IN ('failed','pending') AND i.due_at<=? AND w.consent=1 AND NOT EXISTS(SELECT 1 FROM wa_notifications n WHERE n.reference_id=i.id AND n.kind='payment_failed' AND n.created_at>=?) LIMIT 500",now(),Math.floor(Date.parse(today()+'T00:00:00-03:00')/1000));for(const i of due)await run(env.DB,'INSERT OR IGNORE INTO wa_notifications(id,user_id,kind,reference_id,created_at) VALUES(?,?,?,?,?)','dunning:'+today()+':'+i.id,i.user_id,'payment_failed',i.id,now());}const records=await all(env.DB,"SELECT n.*,c.wa_id,c.consent FROM wa_notifications n JOIN wa_contacts c ON c.user_id=n.user_id JOIN users u ON u.id=n.user_id WHERE n.status='pending' AND n.due_at<=? AND c.consent=1 AND u.disabled=0 LIMIT 50",now());
 for(const n of records){let text;
 if(n.kind.startsWith('appointment_')){const a=await first(env.DB,"SELECT a.*,b.name barber_name FROM appointments a LEFT JOIN users b ON b.id=a.barber_id WHERE a.id=? AND a.status='scheduled'",n.reference_id);if(!a||new Date(a.date+'T'+a.time+':00-03:00')<=Date.now()){await run(env.DB,"UPDATE wa_notifications SET status='canceled' WHERE id=?",n.id);continue}text=(n.kind==='appointment_reminder'?'Lembrete: ':'Confirmado: ')+(SERVICES.find(s=>s.id===a.service)?.name||a.service)+' em '+a.date+' às '+a.time+' com '+a.barber_name+'. Barbearia do João. Envie MEUS HORÁRIOS para consultar ou SAIR para desativar avisos.';
 }else{const i=await first(env.DB,'SELECT * FROM invoices WHERE id=?',n.reference_id),m=await first(env.DB,'SELECT * FROM memberships WHERE user_id=?',n.user_id);if(!i||!m?.customer_id){continue}if(n.kind==='payment_failed'&&i.status==='paid'){await run(env.DB,"UPDATE wa_notifications SET status='canceled' WHERE id=?",n.id);continue}
 if(n.kind==='payment_paid')text='Pagamento confirmado. Obrigado! O status da sua assinatura foi atualizado no aplicativo. Barbearia do João. Envie SAIR para desativar avisos.';
 else {const invoice=await stripe(env,'invoices/'+encodeURIComponent(i.id),null,'GET');if(invoice.status==='paid'){await run(env.DB,"UPDATE wa_notifications SET status='canceled' WHERE id=?",n.id);continue}if(invoice.customer!==m.customer_id)throw err('Inconsistência de cliente.',409);const portal=await stripe(env,'billing_portal/sessions',{customer:m.customer_id,...(env.STRIPE_PORTAL_CONFIGURATION?{configuration:env.STRIPE_PORTAL_CONFIGURATION}:{})},'POST','wa-portal-'+i.id+'-'+Math.floor(now()/300));if(!/^https:\/\/billing\.stripe\.com\//.test(portal.url||''))throw err('Link inválido.',502);text='Olá! O pagamento do seu clube na Barbearia do João não foi aprovado ou precisa de confirmação. Atualize seu cartão com segurança: '+portal.url+' . Não envie dados do cartão pelo WhatsApp. Envie SAIR para desativar avisos.';}}
 await env.DB.batch([env.DB.prepare('INSERT OR IGNORE INTO wa_outbox(id,wa_id,kind,text,created_at) VALUES(?,?,?,?,?)').bind(n.id,n.wa_id,n.kind,text,now()),env.DB.prepare("UPDATE wa_notifications SET status='queued' WHERE id=? AND status='pending'").bind(n.id)]);
 }
 const already=(await first(env.DB,"SELECT COUNT(*) n FROM wa_outbox WHERE sent_at>=?",Math.floor(Date.parse(today()+'T00:00:00-03:00')/1000))).n;const result=await waDrain(env,Math.max(0,Math.min(20,(settings.automation?.dailyLimit||100)-already)));await run(env.DB,"UPDATE automation_runs SET status='success',finished_at=? WHERE id=?",now(),id);
 // Conversation content is deliberately not stored inbound; expire link codes and retained operational data.
 await env.DB.batch([env.DB.prepare('DELETE FROM wa_link_codes WHERE expires_at<?').bind(now()),env.DB.prepare("UPDATE wa_contacts SET pending=NULL WHERE last_inbound<?").bind(now()-86400),env.DB.prepare('DELETE FROM wa_inbox WHERE created_at<?').bind(now()-90*86400),env.DB.prepare("DELETE FROM wa_outbox WHERE created_at<? AND status IN ('sent','delivered','read','canceled')").bind(now()-90*86400)]);return {ok:true,...result};
 }catch(e){await run(env.DB,"UPDATE automation_runs SET status='failed',finished_at=? WHERE id=?",now(),id);throw e}
}
